// Reads a Stripe "checkout.session.completed" event. Anything else is skipped (Stripe already got its 200 reply).
// Stripe re-sends an event when it doesn't get a quick reply, so event ids are remembered to avoid double welcomes.
const event = $json.body ?? {};
const session = event.data?.object ?? {};
const skip = (reason) => ({ json: { skip: true, reason, eventId: event.id ?? null } });

if (event.type !== 'checkout.session.completed') return skip(`Ignored event type: ${event.type ?? 'unknown'}`);
if (session.payment_status !== 'paid') return skip(`Payment not completed (${session.payment_status ?? 'unknown'})`);
const email = String(session.customer_details?.email ?? '').trim().toLowerCase();
if (!email) return skip('No customer email in the event');

const memory = $getWorkflowStaticData('global');
memory.eventIds = memory.eventIds ?? [];
if (memory.eventIds.includes(event.id)) return skip(`Duplicate event ${event.id}`);
memory.eventIds = [...memory.eventIds, event.id].slice(-500);

// Stripe amounts are in the smallest unit (cents), except for zero-decimal currencies like JPY.
const zeroDecimal = ['bif', 'clp', 'djf', 'gnf', 'jpy', 'kmf', 'krw', 'mga', 'pyg', 'rwf', 'ugx', 'vnd', 'vuv', 'xaf', 'xof', 'xpf'];
const currency = String(session.currency ?? '').toLowerCase();
const decimals = zeroDecimal.includes(currency) ? 0 : 2;
const amount = Number(session.amount_total ?? 0) / 10 ** decimals;
const name = String(session.customer_details?.name ?? '').trim();
const goal = String((session.custom_fields ?? []).find((f) => f.key === 'goal')?.text?.value ?? '').trim();

return {
  json: {
    skip: false,
    eventId: event.id,
    customerName: name || email,
    firstName: name.split(/\s+/)[0] || 'there',
    customerEmail: email,
    plan: String(session.metadata?.plan ?? '').trim() || 'your plan',
    goal,
    amountText: `${currency.toUpperCase()} ${amount.toLocaleString('en-US', { minimumFractionDigits: decimals, maximumFractionDigits: decimals })}`,
    paidAt: new Date((event.created ?? Date.now() / 1000) * 1000).toISOString(),
  },
};

// The AI only suggests what the customer can prepare. Everything else is a fixed template,
// and tips are filtered so a customer is never asked for passwords or logins.
const p = $('Settings').item.json;
let ai = $json;
if (!Array.isArray(ai.tips)) {
  try {
    ai = JSON.parse(ai.text);
  } catch {
    ai = {};
  }
}

const fallbackTips = [
  'List the pages or features you want us to look at first.',
  'Gather any photos, logos or texts you want on your site.',
  'Note two websites you like and what you like about them.',
];
const tips = (Array.isArray(ai.tips) ? ai.tips : [])
  .map((t) => String(t).trim())
  .filter((t) => t && t.length <= 140 && !/password|login|log in|credential|access|\bpin\b/i.test(t))
  .slice(0, 3);
for (const tip of fallbackTips) if (tips.length < 3 && !tips.includes(tip)) tips.push(tip);

// "Oct 30, 2026": never ambiguous, always UTC.
const day = 24 * 60 * 60 * 1000;
const pretty = (d) => d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric', timeZone: 'UTC' });
const paidAt = new Date(p.paidAt);
const kickoffBy = pretty(new Date(paidAt.getTime() + 2 * day));
const checkInOn = pretty(new Date(paidAt.getTime() + 7 * day));

const welcomeBody = [
  `Hi ${p.firstName},`,
  '',
  `Thanks for joining ${p.companyName}! Your ${p.plan} plan is active and your payment of ${p.amountText} is confirmed.`,
  '',
  `Next step: book your 30-minute kickoff call here: ${p.kickoffLink}`,
  ...(p.goal ? ['', `You told us your first goal is: "${p.goal}"`] : []),
  '',
  'To get the most out of the call, it helps if you:',
  ...tips.map((t, i) => `${i + 1}. ${t}`),
  '',
  'Questions? Just reply to this email.',
  '',
  `The ${p.companyName} team`,
].join('\n');

const teamBody = [
  `${p.customerName} just paid for ${p.plan}.`,
  '',
  `Email:  ${p.customerEmail}`,
  `Paid:   ${p.amountText} on ${pretty(paidAt)}`,
  `Goal:   ${p.goal || '-'}`,
  '',
  'Onboarding checklist:',
  '[x] Welcome email sent (automatic)',
  `[ ] Kickoff call booked by ${kickoffBy}`,
  '[ ] Website access set up with the customer on the call',
  `[ ] First check-in on ${checkInOn}`,
].join('\n');

return {
  json: {
    customerEmail: p.customerEmail,
    fromEmail: p.fromEmail,
    teamEmail: p.teamEmail,
    companyName: p.companyName,
    tips,
    aiUsed: Array.isArray(ai.tips),
    welcomeSubject: `Welcome to ${p.plan}, ${p.firstName}!`,
    welcomeBody,
    teamSubject: `New customer: ${p.customerName} (${p.plan}, ${p.amountText})`,
    teamBody,
  },
};
